def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []
            markers = []

            while stack:
                x, y = stack.pop()
                component.append((x, y))
                if grid[x][y] > 1:
                    markers.append((x, y, grid[x][y]))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] != 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            if not markers:
                continue

            for x, y in component:
                if grid[x][y] != 1:
                    continue
                if not all(
                    0 <= x + dx < h and 0 <= y + dy < w and
                    grid[x + dx][y + dy] != 0
                    for dx in (-1, 0, 1)
                    for dy in (-1, 0, 1)
                ):
                    continue
                _, _, color = min(
                    markers,
                    key=lambda m: (abs(x - m[0]) + abs(y - m[1]), m[2])
                )
                out[x][y] = color

    return out
